import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`research-report`,heroTitle:`Build research reports in minutes with connectors like Pitchbook, and Statista.`,heroSubtitle:`Perplexity Computer turns a research topic or source URL into a structured report with findings, evidence, gaps, and recommended next steps.`,inputUrlCta:`Build this report`,inputUrlPlaceholder:`topic, source, or brief URL`,inputUrlPrefill:`Go to {url} and build a research report from this topic or source context. 1) Identify the research question, audience, scope, key entities, source types, and decision the report should support. 2) Gather and organize the most relevant findings, evidence, competing viewpoints, gaps, and confidence levels. 3) Create a structured report with executive summary, methodology, key findings, evidence table, implications, risks, and next steps. 4) Include source notes and unanswered questions for follow-up. 5) Deliver a polished research report ready to share with stakeholders.`,heroOverlaySteps:[`Defining the research question, audience, scope, and decision context`,`Gathering findings, evidence, viewpoints, gaps, and confidence levels`,`Structuring the report with summary, methodology, evidence, and implications`,`Polished research report and follow-up questions ready to share`],generatingSteps:[`Visiting {url} to understand the topic, source context, and report audience`,`Designing an agent to gather findings, evidence, viewpoints, and open questions`,`Configuring report structure, evidence tables, implications, and risk notes`,`Setting up the final research report and stakeholder-ready summary`],featureSectionTitle:`From research prompt to stakeholder-ready report`,featureCardTitles:[`Connects to your research stack`,`Outputs you can share`],featureCardDescriptions:[`Computer breaks the report into scope definition, source analysis, evidence organization, synthesis, and report writing.`,`Source URLs, PDFs, Docs, Drive, Notion, Sheets, and Slack can feed one organized research workflow.`,`Executive summary. Findings. Evidence table. Gaps. Implications. Next steps. Computer delivers a report ready for stakeholder review.`],capabilitySectionTitle:`Your research analyst, on autopilot`,capabilitySectionSubtitle:`Paste a topic or source URL and get a complete research report.`,capabilityCards:[{title:`Scope Definition`,description:`Computer can identify the research question, audience, scope, key entities, source types, and decision context.`},{title:`Evidence Synthesis`,description:`Computer can organize findings, supporting evidence, competing viewpoints, confidence levels, and open gaps.`},{title:`Report Drafting`,description:`Computer can build an executive summary, methodology, key findings, evidence table, implications, risks, and next steps.`},{title:`Connect Your Tools`,description:`Computer can organize sources across URLs, PDFs, Docs, Drive, Notion, Sheets, and Slack.`},{title:`Remember Your Format`,description:`Computer can remember your preferred report structure, citation style, confidence labels, and stakeholder summary format.`},{title:`Follow-Up Tracking`,description:`Computer can track unanswered questions and prepare updates when new evidence changes the research picture.`}]});export{t as default};
